        if cleaned.startswith('(') and cleaned.endswith(')'):
            negative = True
            cleaned = cleaned[1:-1]
        value = float(cleaned)
        if negative:
            value = -value
        totals[category] = totals.get(category, 0) + value

    return {k: round(v, 2) for k, v in totals.items()}
